                lo, hi = 0, len(right_pref)
                while lo < hi:
                    mid = (lo + hi) >> 1
                    if gcd(a, right_pref[mid] >> shift) > 1:
                        lo = mid + 1
                    else:
                        hi = mid
                ptr = lo
