            count = item & mask
            if suff[-1] >> shift == g:
                suff[-1] = (g << shift) | ((suff[-1] & mask) + count)
            else:
                suff.append((g << shift) | count)

        return (
            left[0] + right[0],
            tuple(pref),
            tuple(suff),
            left_ans + right_ans + cross,
        )

    size = 1
    while size < n:
        size <<= 1

    tree = [empty] * (2 * size)
    for i, value in enumerate(values):
