        tree[size + i] = (1, (item,), (item,), 0)

    for i in range(size - 1, 0, -1):
        tree[i] = merge(tree[i << 1], tree[i << 1 | 1])

    output = []
    pos = 2 + n

    for _ in range(m):
        typ, x, y = data[pos], data[pos + 1], data[pos + 2]
        pos += 3

        if typ == 1:
            idx = size + x - 1
            item = (y << shift) | 1
            tree[idx] = (1, (item,), (item,), 0)
            idx >>= 1
            while idx:
                tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1])
                idx >>= 1
        else:
            left = x - 1 + size
            right = y + size
            left_result = empty
            right_result = empty

            while left < right:
                if left & 1:
                    left_result = merge(left_result, tree[left])
                    left += 1
